"""Tests for the 3-Coloring -> SAT reduction.

Contains brute-force solvers for both problems (directly from the
docstrings) plus a DPLL SAT solver used for larger instances.  The DPLL
solver is cross-checked against the brute-force solver on small formulas.
"""

from __future__ import annotations

import itertools
import json
import random

from problems import ThreeColoring, Sat
from reduce import reduce


# ----------------------------------------------------------------------
# Brute-force solvers written from the problem definitions.

def solve_three_coloring(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    for colouring in itertools.product(range(3), repeat=n):
        if all(colouring[u] != colouring[v] for u, v in edges):
            return True
    return False


def solve_sat_bruteforce(instance: dict) -> bool:
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            if not any(
                (bits[abs(lit) - 1] if lit > 0 else not bits[abs(lit) - 1])
                for lit in clause
            ):
                ok = False
                break
        if ok:
            return True
    return False


# ----------------------------------------------------------------------
# DPLL SAT solver (correct, handles the larger reductions quickly).

def solve_sat(instance: dict) -> bool:
    clauses = [frozenset(c) for c in instance["clauses"]]
    if any(len(c) == 0 for c in clauses):
        return False

    def dpll(clauses, assignment):
        # Unit propagation.
        while True:
            unit = None
            for clause in clauses:
                unassigned = []
                satisfied = False
                for lit in clause:
                    val = assignment.get(abs(lit))
                    if val is None:
                        unassigned.append(lit)
                    elif (lit > 0) == val:
                        satisfied = True
                        break
                if satisfied:
                    continue
                if not unassigned:
                    return False
                if len(unassigned) == 1:
                    unit = unassigned[0]
                    break
            if unit is None:
                break
            var = abs(unit)
            val = unit > 0
            if var in assignment:
                if assignment[var] != val:
                    return False
            else:
                assignment = dict(assignment)
                assignment[var] = val

        # All clauses satisfied?
        if all(
            any((lit > 0) == assignment[abs(lit)] for lit in clause)
            for clause in clauses
        ):
            return True

        # Pick an unassigned variable and branch.
        for clause in clauses:
            for lit in clause:
                var = abs(lit)
                if var not in assignment:
                    for val in (True, False):
                        branch = dict(assignment)
                        branch[var] = val
                        if dpll(clauses, branch):
                            return True
                    return False
        return True

    return dpll(clauses, {})


# ----------------------------------------------------------------------
# Instance generation.

def random_graph(n: int, p: float, rng: random.Random) -> dict:
    edges = []
    for u in range(n):
        for v in range(u + 1, n):
            if rng.random() < p:
                edges.append([u, v])
    return {"n": n, "edges": edges}


def all_graphs(n: int):
    pairs = [(u, v) for u in range(n) for v in range(u + 1, n)]
    for mask in range(1 << len(pairs)):
        edges = [list(pairs[i]) for i in range(len(pairs)) if mask >> i & 1]
        yield {"n": n, "edges": edges}


# ----------------------------------------------------------------------
# Tests.

def check(instance: dict) -> None:
    ThreeColoring.validate(instance)
    target = reduce(instance)
    Sat.validate(target)
    src = solve_three_coloring(instance)
    tgt = solve_sat(target)
    assert src == tgt, (instance, target, src, tgt)


