    tests_run = 0
    tests_passed = 0

    def run(name, fn):
        nonlocal tests_run, tests_passed
        tests_run += 1
        try:
            fn()
        except AssertionError as exc:
            print(f"FAIL {name}: {exc}")
        else:
            tests_passed += 1

    # Cross-check the DPLL solver against brute force on small formulas.
    rng = random.Random(999)
    for _ in range(200):
        m = rng.randint(0, 5)
        clauses = []
        for _ in range(rng.randint(0, 6)):
            k = rng.randint(0, 3)
            clause = []
